class Node {
    boolean isKey;
    Node[] next = new Node[128];      // one link per ASCII character
}
void add(String key) {
    Node p = root;
    for (int i = 0; i < key.length(); i++) {
        char c = key.charAt(i);
        if (p.next[c] == null) p.next[c] = new Node();
        p = p.next[c];
    }
    p.isKey = true;
}
boolean contains(String key) {
    Node p = root;
    for (int i = 0; i < key.length(); i++) {
        p = p.next[key.charAt(i)];
        if (p == null) return false;          // fell off the trie
    }
    return p.isKey;                           // a prefix alone is not a key
}

List<String> keysWithPrefix(String pre) {
    List<String> out = new ArrayList<>();
    Node p = root;
    for (char c : pre.toCharArray()) { p = p.next[c]; if (p == null) return out; }
    collect(p, pre, out);
    return out;
}
void collect(Node p, String prefix, List<String> out) {
    if (p == null) return;
    if (p.isKey) out.add(prefix);
    for (char c = 0; c < 128; c++) collect(p.next[c], prefix + c, out);
}

