boolean delete(Node p, String s, int d) {
    if (d == s.length()) {
        p.isKey = false;
    } else {
        Node c = p.next.get(s.charAt(d));
        if (c == null) return false;                       // key not present
        if (delete(c, s, d + 1)) p.next.remove(s.charAt(d));
    }
    return !p.isKey && p.next.isEmpty();                    // prune me?
}

int match(Node p, String pat, int d) {
    if (p == null) return 0;
    if (d == pat.length()) return p.isKey ? 1 : 0;
    char c = pat.charAt(d);
    if (c == '.') {
        int total = 0;
        for (Node q : p.next.values()) total += match(q, pat, d + 1);
        return total;
    }
    return match(p.next.get(c), pat, d + 1);
}
